def S(n):
    """Calculates the sum of the digits of n."""
    return sum(int(digit) for digit in str(n))

def check_n(n):
    """Checks if the product S(n)...S(n+37) is not divisible by 11."""
    for k in range(n, n + 38):
        if S(k) % 11 == 0:
            # Found a factor divisible by 11
            return False
    # No factor was divisible by 11
    return True

# Start searching from n=1
n = 1
while True:
    if check_n(n):
        print(f"Found n = {n}")
        break
    n += 1

